<?php
declare(strict_types=1);

const SVLR_CONTRACT_VERSION='2026-10-16-safety-vote-empty-threshold-live-r1';
const SVLR_SERVER_MINIMUM_THRESHOLD=5;

function svlr_config(array$input,int$campaignThreshold=5):array{$enabled=($input['liveLeaderboardEnabled']??$input['LiveLeaderboardEnabled']??false)===true||(int)($input['liveLeaderboardEnabled']??$input['LiveLeaderboardEnabled']??0)===1;$rawTop=$input['liveLeaderboardTopN']??$input['LiveLeaderboardTopN']??null;$top=(int)($rawTop??5);$score=strtolower((string)($input['liveLeaderboardScoreMode']??$input['LiveLeaderboardScoreMode']??'count_percentage'));$visibility=strtolower((string)($input['liveLeaderboardVisibility']??$input['LiveLeaderboardVisibility']??'after_submit'));$rawRefresh=$input['liveLeaderboardRefreshSeconds']??$input['LiveLeaderboardRefreshSeconds']??null;$refresh=(int)($rawRefresh??15);$minimum=max(SVLR_SERVER_MINIMUM_THRESHOLD,$campaignThreshold);$requested=$input['liveLeaderboardPrivacyThreshold']??$input['LiveLeaderboardPrivacyThreshold']??null;$threshold=$requested===null||$requested===''?$minimum:(int)$requested;$errors=[];if($rawTop!==null&&$rawTop!==''&&!in_array($top,[5,10],true))$errors[]=['field'=>'liveLeaderboardTopN','code'=>'INVALID_ENUM'];if(!in_array($top,[5,10],true))$top=5;if($rawRefresh!==null&&$rawRefresh!==''&&($refresh<10||$refresh>60))$errors[]=['field'=>'liveLeaderboardRefreshSeconds','code'=>'OUT_OF_RANGE'];if($refresh<10||$refresh>60)$refresh=15;if(!in_array($score,['count','percentage','count_percentage'],true))$errors[]=['field'=>'liveLeaderboardScoreMode','code'=>'INVALID_ENUM'];if(!in_array($visibility,['after_submit','always','admin_only'],true))$errors[]=['field'=>'liveLeaderboardVisibility','code'=>'INVALID_ENUM'];if($threshold<$minimum||$threshold>100)$errors[]=['field'=>'liveLeaderboardPrivacyThreshold','code'=>'BELOW_PRIVACY_THRESHOLD'];return['ok'=>!$errors,'errors'=>$errors,'value'=>['enabled'=>$enabled,'topN'=>$top,'scoreMode'=>$score,'visibility'=>$visibility,'refreshSeconds'=>$refresh,'privacyThreshold'=>max($minimum,min(100,$threshold))]];}
function svlr_supported(string$type,array$questions):array{if(strtolower($type)!=='popular_vote')return['ok'=>false,'code'=>'LIVE_RESULTS_UNSUPPORTED_CAMPAIGN_TYPE'];if(!$questions)return['ok'=>false,'code'=>'LIVE_RESULTS_NO_QUESTIONS'];foreach($questions as$q)if((int)($q['maxSelections']??$q['MaxSelections']??0)!==1||empty($q['options']))return['ok'=>false,'code'=>'LIVE_RESULTS_UNSUPPORTED_QUESTION_TYPE'];return['ok'=>true,'code'=>null];}
function svlr_aggregate(array$questions,array$answers,int$topN):array{$counts=[];foreach($answers as$row){$qid=(int)($row['QuestionID']??$row['questionId']??0);$oid=(int)($row['OptionID']??$row['optionId']??0);if($qid&&$oid)$counts[$qid.':'.$oid]=($counts[$qid.':'.$oid]??0)+1;}$out=[];foreach($questions as$q){$qid=(int)$q['id'];$valid=0;$ranked=[];foreach($q['options']as$o){$count=$counts[$qid.':'.(int)$o['id']]??0;$valid+=$count;$ranked[]=['optionId'=>(int)$o['id'],'optionCode'=>$o['optionCode']??$o['OptionCode'],'label'=>$o['label']??$o['Label'],'description'=>$o['description']??$o['Description']??null,'fileId'=>!empty($o['fileId']??$o['FileID'])?(int)($o['fileId']??$o['FileID']):null,'voteCount'=>$count];}usort($ranked,fn($a,$b)=>$b['voteCount']<=>$a['voteCount']?:$a['optionId']<=>$b['optionId']);$previous=null;foreach($ranked as$i=>&$o){$o['rank']=$previous!==null&&$o['voteCount']===$previous?$ranked[$i-1]['rank']:$i+1;$previous=$o['voteCount'];$o['percentage']=$valid?round($o['voteCount']/$valid*100,2):0;$o['tied']=count(array_filter($ranked,fn($x)=>$x['optionId']!==$o['optionId']&&$x['voteCount']===$o['voteCount']))>0;}unset($o);$out[]=['questionId'=>$qid,'questionCode'=>$q['questionCode']??$q['QuestionCode'],'title'=>$q['title']??$q['Title'],'validAnswerCount'=>$valid,'denominatorPolicy'=>'valid_option_answers_including_abstain','options'=>$ranked,'summary'=>array_values(array_filter($ranked,fn($o)=>$o['rank']<=$topN))];}return$out;}
function svlr_masked_questions(array$questions,int$topN,bool$empty=false):array{$out=[];foreach($questions as$q){$options=[];foreach($q['options']as$i=>$o)$options[]=['optionId'=>(int)$o['id'],'optionCode'=>$o['optionCode']??$o['OptionCode'],'label'=>$o['label']??$o['Label'],'description'=>$o['description']??$o['Description']??null,'fileId'=>!empty($o['fileId']??$o['FileID'])?(int)($o['fileId']??$o['FileID']):null,'displayPosition'=>$i+1,'rank'=>null,'voteCount'=>$empty?0:null,'percentage'=>$empty?0:null,'tied'=>false,'pending'=>true];$out[]=['questionId'=>(int)$q['id'],'questionCode'=>$q['questionCode']??$q['QuestionCode'],'title'=>$q['title']??$q['Title'],'validAnswerCount'=>$empty?0:null,'denominatorPolicy'=>'valid_option_answers_including_abstain','scoreDisclosure'=>$empty?'zero':'masked','options'=>$options,'summary'=>array_slice($options,0,$topN)];}return$out;}
